<?php require __DIR__.'/app/layout.php';must_admin();
$id=(int)($_GET['edit']??0);$edit=$id?one_row('SELECT * FROM rooms WHERE id=?',[$id]):null;
if($id&&!$edit){flash('Salle introuvable.','danger');go('gestion.php');}
$rooms=all_rows('SELECT s.*, (SELECT COUNT(*) FROM reservations r WHERE r.room_id=s.id) AS reservations_total FROM rooms s ORDER BY s.id DESC');
page_start('Gestion des salles','management');titlebar('Administration','Gestion des salles','Créez, modifiez, archivez les salles et leurs équipements.'); ?>
<div class="row g-4"><div class="col-xl-4"><div class="panel"><div class="panel-head"><h3><?= $edit?'Modifier la salle':'Ajouter une salle' ?></h3><?php if($edit):?><a href="<?=h(url('gestion.php'))?>" class="btn btn-sm btn-light border">Nouvelle</a><?php endif;?></div>
<form action="<?=h(url('actions.php'))?>" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="room_save"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div class="mb-3"><label class="form-label">Nom *</label><input class="form-control" name="name" maxlength="150" required value="<?=h($edit['name']??'')?>"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3" maxlength="5000"><?=h($edit['description']??'')?></textarea></div><div class="row g-2 mb-3"><div class="col-5"><label class="form-label">Capacité *</label><input type="number" min="1" max="100000" class="form-control" name="capacity" required value="<?=h($edit['capacity']??'')?>"></div><div class="col-7"><label class="form-label">Statut</label><select class="form-select" name="status"><?php foreach(['active','maintenance','archived'] as $s):?><option value="<?=h($s)?>" <?=($edit['status']??'active')===$s?'selected':''?>><?=h(status_text($s))?></option><?php endforeach;?></select></div></div><div class="mb-3"><label class="form-label">Emplacement</label><input class="form-control" name="location" maxlength="150" value="<?=h($edit['location']??'')?>"></div><div class="mb-3"><label class="form-label">Équipements</label><textarea class="form-control" name="equipment" rows="2" maxlength="2000" placeholder="Wi-Fi, écran, vidéoprojecteur…"><?=h($edit['equipment']??'')?></textarea></div><div class="mb-4"><label class="form-label">Image (JPEG, PNG, WebP, max. 5 Mo)</label><input class="form-control" type="file" name="image" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"><?php if(!empty($edit['image'])):?><img alt="Image actuelle" class="room-cover mt-2" style="max-height:120px" src="<?=h(room_image($edit['image']))?>"><?php endif;?></div><?php submit_button($edit?'Mettre à jour':'Ajouter la salle');?></form></div></div>
<div class="col-xl-8"><div class="panel"><div class="panel-head"><h3>Salles enregistrées (<?=count($rooms)?>)</h3></div><input class="form-control mb-3" data-table-search placeholder="Rechercher une salle…"><div class="table-responsive"><table class="table"><thead><tr><th>Salle</th><th>Capacité</th><th>État</th><th>Réservations</th><th>Actions</th></tr></thead><tbody><?php foreach($rooms as $r):?><tr data-search-row><td><div class="d-flex gap-2 align-items-center"><img src="<?=h(room_image($r['image']))?>" alt="" style="width:54px;height:42px;object-fit:cover;border-radius:8px"><div><strong><?=h($r['name'])?></strong><div class="muted small"><?=h($r['location'])?></div></div></div></td><td><?=h($r['capacity']??'—')?></td><td><?=pill($r['status'])?></td><td><?=h($r['reservations_total'])?></td><td><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="<?=h(url('gestion.php?edit='.$r['id']))?>" title="Modifier"><i class="bi bi-pencil"></i></a><?php if($r['status']!=='archived'):?><form method="post" action="<?=h(url('actions.php'))?>" data-confirm="Archiver cette salle (réservations conservées) ?"><?=csrf_field()?><input type="hidden" name="action" value="room_archive"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-sm btn-outline-danger" title="Archiver"><i class="bi bi-archive"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rooms):?><tr><td colspan="5" class="empty-state">Aucune salle enregistrée.</td></tr><?php endif;?></tbody></table></div></div></div></div>
<?php page_end();?>
